function list(value){return[...new Set((Array.isArray(value)?value:value&&value!=='none'?[value]:[]).filter(Boolean))]}
function hash(value){let h=2166136261;for(const c of String(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function ageFrom(date){if(!date)return 25;const born=new Date(date+'T00:00:00'),now=new Date();let age=now.getFullYear()-born.getFullYear();if(now<new Date(now.getFullYear(),born.getMonth(),born.getDate()))age--;return Math.max(14,Math.min(90,age||25))}
function safetyCheck(health={}){const conditions=list(health.medical_conditions),reasons=conditions.filter(x=>reviewConditions.has(x)),requiresReview=Boolean(health.requires_review||reasons.length);return{allowed:!requiresReview||health.medical_clearance===true,requiresReview,reasons}}
